#include <datamunge/optim/trust_region_newton.hpp>
#include <cmath>
#include <stdexcept>
namespace datamunge::optim { TrustRegionNewton::TrustRegionNewton(TrustRegionNewtonOptions o):options_(o){} double TrustRegionNewton::optimize(HessianFunction& f,std::vector<double>& x)const{if(options_.initial_radius<=0)throw std::invalid_argument("TrustRegionNewton: initial_radius must be positive");double r=options_.initial_radius,v=f.evaluate(x);for(std::size_t k=0;k<options_.max_iterations;++k){auto g=f.gradient(x);auto h=f.hessian(x);double gg=0,ghg=0;for(std::size_t i=0;i<x.size();++i){gg+=g[i]*g[i];for(std::size_t j=0;j<x.size();++j)ghg+=g[i]*h[i][j]*g[j];}if(std::sqrt(gg)<=options_.tolerance)break;double a=ghg>0?std::min(gg/ghg,r/std::sqrt(gg)):r/std::sqrt(gg);std::vector<double> y=x;for(std::size_t i=0;i<x.size();++i)y[i]-=a*g[i];double nv=f.evaluate(y);if(nv<v){x=std::move(y);v=nv;r=std::min(options_.max_radius,2*r);}else r*=.5;if(r<=options_.tolerance)break;}return v;}}
